import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.qXLDknWC.js";const p=JSON.parse('{"title":"CharacterVault 1.4.0","description":"","frontmatter":{},"headers":[],"relativePath":"releases/v1.4.0.md","filePath":"releases/v1.4.0.md"}'),n={name:"releases/v1.4.0.md"};function r(i,e,l,h,d,g){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="charactervault-1-4-0" tabindex="-1">CharacterVault 1.4.0 <a class="header-anchor" href="#charactervault-1-4-0" aria-label="Permalink to &quot;CharacterVault 1.4.0&quot;">​</a></h1><p>This release adds the <strong>Agent</strong>: a chat that reads and edits the open character or lorebook through tools, instead of you copying text out of Orion. It works in the character workspace and in the standalone lorebook vault.</p><p><strong>Try it:</strong> <a href="https://spaceman2408.github.io/CharacterVault" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault</a><br><strong>Docs:</strong> <a href="https://spaceman2408.github.io/CharacterVault/docs/" target="_blank" rel="noreferrer">https://spaceman2408.github.io/CharacterVault/docs/</a></p><hr><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h3><p>A tool-using alternative to Orion. You describe the fill, rewrite, or cut; the Agent looks at the card (or book) and applies the edits.</p><ul><li><strong>Character workspace</strong> — works on spec fields, alternate greetings, and the lorebook on the card. One session is shared across workspace tabs, so it keeps context as you move between sections.</li><li><strong>Standalone lorebooks</strong> — the same Agent in a vault book, with tools to list, read, add, update, snippet-edit, and delete entries.</li><li><strong>Snippet edits</strong> — unique-match replace on fields and entries, instead of rewriting the whole value. Matching tolerates quote styles and section spans.</li><li><strong>Whole-book &amp; whole-card tools</strong> — search across entries and spec fields, replace a phrase everywhere with one call, and audit the book or card for totals: token counts, duplicate keys, empty fields, recursion edges and cycles. On the card: <strong>append to a field</strong> without rewriting it and <strong>move an alternate greeting</strong> to reorder. Entry writes accept the usual SillyTavern activation and recursion flags.</li><li><strong>Readable tool results</strong> — tool calls render as short color-coded lines so you can see what it looked at and changed, without dumping full field text into the thread. Searches and audits stay off the transcript entirely.</li><li><strong>Live token count</strong> — the context meter updates as the prompt grows, including tool results.</li><li><strong>Own model</strong> — <strong>Settings → Prompts → Agent</strong> can bind a provider and model independent of Orion and the toolbar. Default still follows <strong>AI Config</strong>.</li><li><strong>Native function calling</strong> — when the provider accepts OpenAI-style <code>tools</code>, the Agent uses them. If the provider rejects that, it falls back to XML tool calls. Agent completions use a larger output budget than the Sampler <strong>Max Tokens</strong> slider so calls are less likely to cut off.</li><li><strong>Cleaner chat</strong> — flatter message chrome, streamed <strong>Thinking</strong> (starts expanded while it is live), visible lorebook entry ids, and no extra turns for lookup-only reads.</li><li><strong>Reply timing</strong> — time-to-first-token and tokens-per-second on the assistant tooltip, same as Orion.</li><li><strong>Default chat</strong> — <strong>Settings → Studio → Chat panel</strong> can open Ask AI on Orion or the Agent. The header toggle still switches for the current session.</li></ul><p>The Agent writes once when the run finishes (one snapshot first). Until then, the editor keeps the previous text.</p><p><a href="/CharacterVault/docs/features/ai-agent">AI Agent →</a> · <a href="/CharacterVault/docs/configuration/ai-setup#prompts-tab">AI Setup → Prompts</a></p><h3 id="also-in-this-release" tabindex="-1">Also in this release <a class="header-anchor" href="#also-in-this-release" aria-label="Permalink to &quot;Also in this release&quot;">​</a></h3><ul><li><strong>NanoGPT cache routing</strong> — a new <strong>Cache-capable provider routing</strong> toggle under <strong>Settings → AI Config → NanoGPT Options</strong> sends <code>caching: true</code> on chat completions, so NanoGPT routes to a provider that supports prompt caching for lower cost and latency. Sticky provider routing is on by default; if no cache-capable provider serves a model, the request fails rather than silently falling back. Works alongside an explicit Provider choice.</li><li><strong>Shared Thinking fold</strong> — the same <strong>Thinking</strong> control is used in Orion, the Agent, and the inline editor toolbar. Live chat thinking starts expanded; the toolbar stays collapsed.</li><li><strong>History</strong> — the snapshot of the card you currently have open stays pinned to the <strong>end</strong> of the list (newest saves still appear at the top).</li></ul><hr><h2 id="fixes-and-performance" tabindex="-1">Fixes and performance <a class="header-anchor" href="#fixes-and-performance" aria-label="Permalink to &quot;Fixes and performance&quot;">​</a></h2><ul><li><strong>Streaming memory leak</strong> — a finished AI reply could leave its stream hanging open on gateways that keep the connection alive, slowly growing memory while the app sat idle. Streams now stop when the reply signals its end.</li><li><strong>Leaving mid-run</strong> — closing a character or leaving the editor aborts an in-flight Orion or Agent run cleanly, and pending edits save first.</li><li><strong>Snapshots</strong> — History, pruning, and image cleanup read a lightweight metadata index instead of loading every snapshot payload into memory. Snapshot hashes no longer include the card’s base64 image. Selecting a revision keeps only what is on screen in RAM.</li><li><strong>Long AI sessions</strong> — token streams buffer in chunks instead of recopying the full text on every token. Agent chats keep the last 100 messages. Committed thinking is clipped to a generous tail, and a runaway thinking stream rotates its buffer instead of growing forever.</li><li><strong>Agent meter</strong> — while a live prompt count is on screen, the idle catalog estimate is skipped so the meter does not rebuild after every message.</li><li><strong>Token estimates</strong> — AI features reuse one encoder instead of allocating a new one on every call.</li><li><strong>Toolbar</strong> — the ✕ next to a running operation is gone (Stop covers it). A ✕ appears only on errors, where it dismisses them.</li><li><strong>Lorebook links</strong> — attaching or deleting a vault-linked book keeps the vault’s link list in sync.</li><li><strong>Agent writes</strong> — lorebook edits flush to the attached vault book instead of being left pending. Alternate greetings are numbered from 1, matching the editor. Duplicate same-name <code>add_entry</code> calls collapse into one entry.</li><li><strong>Lorebook entries</strong> — the entry list holds a stable order (sorted by id) while you filter, so rows no longer shuffle as you type.</li><li><strong>Chat</strong> — stopping mid-thinking no longer jams the composer (the turn is retryable and Send works again). Messages no longer clip while scrolling.</li></ul><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><p>Client-only app. Open the hosted site or rebuild locally; no server migration.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/spaceman2408/CharacterVault</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CharacterVault</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Local data from 1.3.x keeps working. IndexedDB gains snapshot metadata index tables the first time you open this build (schema version 10). Existing snapshots are indexed in place; you do not need to export first.</p><p>Hard refresh if the UI looks stale after deploy.</p><hr><h2 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/ai-agent">AI Agent</a> — expanded with a tool-calling troubleshooting guide for models that ignore or break tool calls</li><li><a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a></li><li><a href="/CharacterVault/docs/features/snapshots-history">Snapshots &amp; Rollback</a></li><li><a href="/CharacterVault/docs/faq">FAQ</a></li><li><a href="/CharacterVault/docs/whats-new">What&#39;s New</a></li><li><a href="/CharacterVault/docs/changelog">Changelog</a></li></ul>`,24)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
